class Solution:
    def checkStrings(self, s1: str, s2: str) -> bool:
        return sorted(s1[0::2]) == sorted(s2[0::2]) and sorted(s1[1::2]) == sorted(s2[1::2])

class Solution {
public:
    bool checkStrings(string s1, string s2) {
        vector<int> cntEven(26, 0), cntOdd(26, 0);
        int n = s1.size();
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                cntEven[s1[i] - 'a']++;
                cntEven[s2[i] - 'a']--;
            } else {
                cntOdd[s1[i] - 'a']++;
                cntOdd[s2[i] - 'a']--;
            }
        }
        for (int i = 0; i < 26; i++) {
            if (cntEven[i] != 0 || cntOdd[i] != 0) return false;
        }
        return true;
    }
};

class Solution {
    public boolean checkStrings(String s1, String s2) {
        int[] cntEven = new int[26];
        int[] cntOdd = new int[26];
        int n = s1.length();
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                cntEven[s1.charAt(i) - 'a']++;
                cntEven[s2.charAt(i) - 'a']--;
            } else {
                cntOdd[s1.charAt(i) - 'a']++;
                cntOdd[s2.charAt(i) - 'a']--;
            }
        }
        for (int i = 0; i < 26; i++) {
            if (cntEven[i] != 0 || cntOdd[i] != 0) return false;
        }
        return true;
    }
}

