var checkStrings = function(s1, s2) {
    const cntEven = new Array(26).fill(0);
    const cntOdd = new Array(26).fill(0);
    const n = s1.length;
    for (let i = 0; i < n; i++) {
        const c1 = s1.charCodeAt(i) - 97;
        const c2 = s2.charCodeAt(i) - 97;
        if (i % 2 === 0) {
            cntEven[c1]++;
            cntEven[c2]--;
        } else {
            cntOdd[c1]++;
            cntOdd[c2]--;
        }
    }
    for (let i = 0; i < 26; i++) {
        if (cntEven[i] !== 0 || cntOdd[i] !== 0) return false;
    }
    return true;
};
